script:
function resolve(input) {
  function destination(value) {
    return typeof value === 'string' && /^https:\/\/(?:www\.)?filecrypt\.cc\/Container\/[A-Za-z0-9_-]+\.html(?:[?#].*)?$/.test(value) ? {url:value} : null;
  }
  var links=input.links || [], net=input.network || {}, result;
  for(var i=0;i<links.length;i++){result=destination(links[i].href);if(result)return result;}
  result=destination(net.location);if(result)return result;
  var ready=net.links || [];
  for(var j=0;j<ready.length;j++){result=destination(ready[j].href);if(result)return result;}
  return null;
}
